		this.onAddItem = host::addItem;
		this.onUntrackToPreview = host::untrackToPreview;
		buildDetailCard();
		buildDetailLoadingCard();
		detailLoadTimeout = new Timer(12000, e ->
		{
			detailLoadTimedOut = true;
			applyDetailCard();
