	/** Appends a new empty acquisition row to the table and scrolls it into view. */
	private void acqAddRow(JTable table, AcquisitionsTableModel model)
	{
		TrackedItem t = host.trackedItem(boundItemId);
		if (t == null)
			return;

		long price = t.getAvgPrice() > 0 ? t.getAvgPrice() : 0;
		host.editAcquisitions(boundItemId,
				records -> records.add(new AcquisitionRecord(0, price, null, AcquisitionSource.MANUAL)),
				() ->
				{
					model.fireTableDataChanged();
					table.revalidate();
					JScrollPane sp = (JScrollPane) SwingUtilities.getAncestorOfClass(JScrollPane.class, table);
					if (sp != null)
					{
						SwingUtilities.invokeLater(() ->
						{
							JScrollBar bar = sp.getVerticalScrollBar();
							bar.setValue(bar.getMaximum());
						});
					}

					int newRow = model.getRowCount() - 1;
					if (newRow >= 0 && table.editCellAt(newRow, 0))
					{
						table.changeSelection(newRow, 0, false, false);
						Component editor = table.getEditorComponent();
						if (editor != null)
							editor.requestFocusInWindow();
					}
				});
	}

	/** Removes the selected acquisition rows and commits the change. */
	private void acqRemoveSelected(JTable table, AcquisitionsTableModel model)
	{
		TrackedItem t = host.trackedItem(boundItemId);
		if (t == null)
			return;

		if (table.isEditing())
			table.getCellEditor().stopCellEditing();

		Set<AcquisitionRecord> doomed = selectedLots(table, model);
		if (doomed.isEmpty())
			return;

		host.editAcquisitions(boundItemId, records -> records.removeIf(doomed::contains), () ->
		{
			model.fireTableDataChanged();
			table.revalidate();
		});
	}

	/**
	 * @return the lots behind a table's selected rows, compared by identity. Removal used to delete by
	 *         row index on the client thread, which deleted the wrong lot whenever the engine had removed
	 *         or merged an earlier one in the meantime (#374).
	 */
	private static Set<AcquisitionRecord> selectedLots(JTable table, AcquisitionsTableModel model)
	{
		Set<AcquisitionRecord> lots = Collections.newSetFromMap(new IdentityHashMap<>());
		for (int row : table.getSelectedRows())
		{
			AcquisitionRecord rec = model.recordAt(row);
			if (rec != null)
				lots.add(rec);
		}

		return lots;
	}

	/** Consolidates the acquisitions log, merging like rows and dropping empty ones. */
	private void acqClean(AcquisitionsTableModel model)
	{
		TrackedItem t = host.trackedItem(boundItemId);
		if (t == null)
			return;

		host.editAcquisitions(boundItemId, records -> records.removeIf(r -> r.getQuantity() == 0),
				model::fireTableDataChanged);
	}

	/**
	 * Clears all acquisitions for the current item after confirmation, via the plugin callback, first
	 * cancelling any cell edit in progress on {@code table} so it can't write back into a cleared log.
	 * Shared by the card's and the pop-out's Clear buttons, which used to carry two copies of it.
	 */
	private void acqClear(JTable table)
	{
		TrackedItem t = host.trackedItem(boundItemId);
		if (t == null || t.getLotsSnapshot().isEmpty())
			return;

		int choice = JOptionPane.showConfirmDialog(
				DetailView.this,
				"Clear the entire collection log for this item?",
				"Clear Collection Log",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE);
		if (choice != JOptionPane.YES_OPTION)
			return;

		if (table.isEditing())
			table.getCellEditor().cancelCellEditing();

		if (onClearAcquisitions != null)
			onClearAcquisitions.accept(boundItemId);
	}

	/** Paints the small box-with-arrow "open in new window" icon used by pop-out buttons. */
	private Icon buildPopoutIcon()
	{
		int s = 11;
		BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.setStroke(new BasicStroke(1f));

		g.drawRect(0, 4, 6, 6);
		g.drawLine(4, 6, s - 1, 0);
		g.drawLine(s - 5, 0, s - 1, 0);
		g.drawLine(s - 1, 0, s - 1, 4);
		g.dispose();
		return new ImageIcon(img);
	}

