	/** Builds a sidebar-sized price chart. */
	public PriceGraphPanel()
	{
		this(Mode.PRICE, false);
	}

	/** Builds a sidebar-sized chart in the given mode. */
	public PriceGraphPanel(Mode mode)
	{
